34	/// JIT'd memory management backend.
35	///
36	/// Intances can:
37	/// 1. Reserve address space.
38	/// 2. Initialize memory regions within reserved memory (copying content,
39	///    applying permissions, running finalize actions, and recording
40	///    deallocate actions).
41	/// 3. Deinitialize memory regions within reserved memory (running
42	///    deallocate actions and making memory available for future
43	///    initialize calls (if the system permits this).
44	/// 4. Release address space, deinitializing any remaining initialized
45	///    regions, and returning the address space to the system for reuse (if
46	///    the system permits).
47	class SimpleNativeMemoryMap : public Service {
48	public:
49	  /// Create a SimpleNativeMemoryMap, adding associated symbols to the given
50	  /// SimpleSymbolTable (typically the BootstrapInfo table).
51	  static Expected<std::unique_ptr<SimpleNativeMemoryMap>>
52	  Create(Session &S, SimpleSymbolTable &ST,
53	         const char *InstanceName = "orc_rt_ci_SimpleNativeMemoryMap_Instance",
54	         SimpleSymbolTable::MutatorFn AddInterface =
55	             sps_ci::addSimpleNativeMemoryMap);
56	
57	  /// Convenience constructor that adds default symbols to the given
58	  /// BootstrapInfo's symbols map.
59	  static Expected<std::unique_ptr<SimpleNativeMemoryMap>>
60	  Create(Session &S, BootstrapInfo &BI) {
61	    return Create(S, BI.symbols());
62	  }
63	  /// SimpleNativeMemoryMap is not copyable / moveable.
64	  SimpleNativeMemoryMap(const SimpleNativeMemoryMap &) = delete;
65	  SimpleNativeMemoryMap &operator=(const SimpleNativeMemoryMap &) = delete;
66	  SimpleNativeMemoryMap(SimpleNativeMemoryMap &&) = delete;
67	  SimpleNativeMemoryMap &operator=(SimpleNativeMemoryMap &&) = delete;
68	
69	  /// Reserves a slab of contiguous address space for allocation.
70	  ///
71	  /// Returns the base address of the allocated memory.
72	  using OnReserveCompleteFn = move_only_function<void(Expected<void *>)>;
73	  void reserve(OnReserveCompleteFn &&OnComplete, size_t Size);
74	
75	  /// Release a slab of contiguous address space back to the system.
76	  using OnReleaseCompleteFn = move_only_function<void(Error)>;
77	  void release(OnReleaseCompleteFn &&OnComplete, void *Addrs);
78	
79	  /// Convenience method to release multiple slabs with one call. This can be
80	  /// used to save on interprocess communication at the cost of less expressive
81	  /// errors.
82	  void releaseMultiple(OnReleaseCompleteFn &&OnComplete,
83	                       std::vector<void *> Addrs);
84	
85	  struct InitializeRequest {
86	    struct Segment {
87	      AllocGroup AG;
88	      char *Address = nullptr;
89	      size_t Size = 0;
90	      span<const char> Content;
91	    };
92	
93	    std::vector<Segment> Segments;
94	    std::vector<AllocActionPair> AAPs;
95	  };
96	
97	  /// Writes content into the requested ranges, applies permissions, and
98	  /// performs allocation actions.
99	  using OnInitializeCompleteFn = move_only_function<void(Expected<void *>)>;
100	  void initialize(OnInitializeCompleteFn &&OnComplete, InitializeRequest IR);
101	
102	  /// Runs deallocation actions and resets memory permissions for the requested
103	  /// memory.
104	  using OnDeinitializeCompleteFn = move_only_function<void(Error)>;
105	  void deinitialize(OnDeinitializeCompleteFn &&OnComplete, void *Base);
106	
107	  /// Convenience method to deinitialize multiple regions with one call. This
108	  /// can be used to save on interprocess communication at the cost of less
109	  /// expressive errors.
110	  void deinitializeMultiple(OnDeinitializeCompleteFn &&OnComplete,
111	                            std::vector<void *> Bases);
112	
113	  void onDetach(Service::OnCompleteFn OnComplete,
114	                bool ShutdownRequested) override;
115	  void onShutdown(Service::OnCompleteFn OnComplete) override;
116	
117	private:
118	  SimpleNativeMemoryMap(Session &S) : S(S) {}
119	
120	  struct SlabInfo {
121	    SlabInfo(size_t Size) : Size(Size) {}
122	    size_t Size;
123	    std::unordered_map<void *, std::vector<AllocAction>> DeallocActions;
124	  };
125	
126	  void releaseNext(OnReleaseCompleteFn &&OnComplete, std::vector<void *> Addrs,
127	                   bool AnyError, Error LastErr);
128	  void deinitializeNext(OnDeinitializeCompleteFn &&OnComplete,
129	                        std::vector<void *> Bases, bool AnyError,
130	                        Error LastErr);
131	  void shutdownNext(OnCompleteFn OnComplete, std::vector<void *> Bases);
132	  Error makeBadSlabError(void *Base, const char *Op);
133	  SlabInfo *findSlabInfoFor(void *Base);
134	  Error recordDeallocActions(void *Base,
135	                             std::vector<AllocAction> DeallocActions);
136	
137	  Session &S;
138	  std::mutex M;
139	  std::map<void *, SlabInfo> Slabs;
140	};
