25	/// Describes Read/Write/Exec permissions for memory.
26	enum class MemProt : unsigned {
27	  None = 0,
28	  Read = 1U << 0,
29	  Write = 1U << 1,
30	  Exec = 1U << 2,
31	  ORC_RT_MARK_AS_BITMASK_ENUM(/* LargestValue = */ Exec)
32	};
33	
34	/// Describes a memory lifetime policy.
35	enum class MemLifetime : unsigned {
36	  /// Standard memory should be deallocated by the corresponding call to
37	  /// deallocate.
38	  Standard,
39	
40	  /// Finalize memory should be deallocated at the end of the finalization
41	  /// process.
42	  Finalize
43	};
44	
45	namespace detail {
46	struct AllocGroupInternals;
47	} // namespace detail
48	
49	/// A pair of memory protections and lifetime policy.
50	class AllocGroup {
51	  friend struct detail::AllocGroupInternals;
52	
53	private:
54	  static constexpr int NumProtBits = bitmask_enum_num_bits_v<MemProt>;
55	  static constexpr int NumLifetimeBits = 1;
56	  static constexpr int NumBits = NumProtBits + NumLifetimeBits;
57	
58	  typedef uint8_t underlying_type;
59	
60	  static_assert(NumBits <= std::numeric_limits<underlying_type>::digits,
61	                "Not enough bits to hold (prot, lifetime) pair");
62	
63	  constexpr static underlying_type ProtMask = (1U << NumProtBits) - 1;
64	  constexpr static underlying_type LifetimeMask = (1U << NumLifetimeBits) - 1;
65	
66	public:
67	  static constexpr size_t MaxValues = 1U << NumBits;
68	
69	  AllocGroup() = default;
70	  AllocGroup(MemProt MP, MemLifetime ML = MemLifetime::Standard)
71	      : Id((static_cast<underlying_type>(ML) << NumProtBits) |
72	           static_cast<underlying_type>(MP)) {}
73	
74	  MemProt getMemProt() const { return static_cast<MemProt>(Id & ProtMask); }
75	
76	  MemLifetime getMemLifetime() const {
77	    return static_cast<MemLifetime>((Id >> NumProtBits) & LifetimeMask);
78	  }
79	
80	  friend bool operator==(const AllocGroup &LHS, const AllocGroup &RHS) {
81	    return LHS.Id == RHS.Id;
82	  }
83	
84	  friend bool operator!=(const AllocGroup &LHS, const AllocGroup &RHS) {
85	    return !(LHS == RHS);
86	  }
87	
88	  friend bool operator<(const AllocGroup &LHS, const AllocGroup &RHS) {
89	    return LHS.Id < RHS.Id;
90	  }
91	
92	private:
93	  underlying_type Id = 0;
94	};
95	
96	namespace detail {
97	/// Helper for serializers that need access to the underlying representation of
98	/// AllocGroup.
99	struct AllocGroupInternals {
100	  typedef AllocGroup::underlying_type underlying_type;
101	  static underlying_type getId(const AllocGroup &AG) noexcept { return AG.Id; }
102	  static AllocGroup fromId(underlying_type Id) noexcept {
103	    AllocGroup AG;
104	    AG.Id = Id;
105	    return AG;
106	  }
107	};
108	} // namespace detail
