110	/// A specialized small-map for AllocGroups.
111	///
112	/// Iteration order is guaranteed to match key ordering.
113	template <typename T> class AllocGroupSmallMap {
114	private:
115	  using ElemT = std::pair<AllocGroup, T>;
116	  using VectorTy = std::vector<ElemT>;
117	
118	  static bool compareKey(const ElemT &E, const AllocGroup &G) {
119	    return E.first < G;
120	  }
121	
122	public:
123	  using iterator = typename VectorTy::iterator;
124	
125	  AllocGroupSmallMap() = default;
126	  AllocGroupSmallMap(std::initializer_list<std::pair<AllocGroup, T>> Inits)
127	      : Elems(Inits) {
128	    std::sort(Elems, [](const ElemT &LHS, const ElemT &RHS) {
129	      return LHS.first < RHS.first;
130	    });
131	  }
132	
133	  iterator begin() { return Elems.begin(); }
134	  iterator end() { return Elems.end(); }
135	  iterator find(AllocGroup G) {
136	    auto I = std::lower_bound(Elems.begin(), Elems.end(), G, compareKey);
137	    return (I == end() || I->first == G) ? I : end();
138	  }
139	
140	  bool empty() const { return Elems.empty(); }
141	  size_t size() const { return Elems.size(); }
142	
143	  T &operator[](AllocGroup G) {
144	    auto I = std::lower_bound(Elems.begin(), Elems.end(), G, compareKey);
145	    if (I == Elems.end() || I->first != G)
146	      I = Elems.insert(I, std::make_pair(G, T()));
147	    return I->second;
148	  }
149	
150	private:
151	  VectorTy Elems;
152	};
