23	namespace orc_rt {
24	
25	/// An AllocActionFn is a function that takes an argument blob and returns an
26	/// empty WrapperFunctionBuffer on success, or an out-of-band error on failure.
27	typedef orc_rt_WrapperFunctionBuffer (*AllocActionFn)(const char *ArgData,
28	                                                      size_t ArgSize);
29	
30	struct AllocActionFunction {
31	
32	  template <typename Deserializer, typename Serializer, typename Handler>
33	  static WrapperFunctionBuffer handle(const char *ArgData, size_t ArgSize,
34	                                      Deserializer &&D, Serializer &&S,
35	                                      Handler &&H) {
36	    typename CallableArgInfo<Handler>::args_tuple_type Args;
37	    if (!D.deserialize(ArgData, ArgSize, Args))
38	      return WrapperFunctionBuffer::createOutOfBandError(
39	          "Could not deserialize allocation action argument buffer");
40	
41	    return S.serialize(std::apply(std::forward<Handler>(H), std::move(Args)));
42	  }
43	};
44	
45	/// An AllocAction is a pair of an AllocActionFn and an argument data buffer.
46	struct AllocAction {
47	  AllocAction() = default;
48	  AllocAction(AllocActionFn Fn, WrapperFunctionBuffer ArgData)
49	      : Fn(Fn), ArgData(std::move(ArgData)) {}
50	
51	  [[nodiscard]] WrapperFunctionBuffer operator()() {
52	    assert(Fn && "Attempt to call null action");
53	    return WrapperFunctionBuffer(Fn(ArgData.data(), ArgData.size()));
54	  }
55	
56	  explicit operator bool() const noexcept { return !!Fn; }
57	
58	  AllocActionFn Fn = nullptr;
59	  WrapperFunctionBuffer ArgData;
60	};
61	
62	/// An AllocActionPair is a pair of a Finalize action and a Dealloc action.
63	struct AllocActionPair {
64	  AllocAction Finalize;
65	  AllocAction Dealloc;
66	};
67	
68	/// Run the finalize actions in the given sequence.
69	///
70	/// On success, returns the list of deallocation actions to be run in reverse
71	/// order at deallocation time.
72	///
73	/// On failure, runs deallocation actions associated with any previously
74	/// successful finalize actions, then returns an error.
75	///
76	/// Both finalize and dealloc actions are permitted to be null (i.e. have a
77	/// null action function) in which case they are ignored.
78	template <typename ReportErrorFn>
79	Expected<std::vector<AllocAction>>
80	runFinalizeActions(std::vector<AllocActionPair> AAPs,
81	                   ReportErrorFn &&ReportError) {
82	  std::vector<AllocAction> DeallocActions;
83	  auto RunDeallocActions = scope_exit([&]() {
84	    while (!DeallocActions.empty()) {
85	      auto B = DeallocActions.back()();
86	      if (auto *ErrMsg = B.getOutOfBandError())
87	        ReportError(make_error<StringError>(ErrMsg));
88	      DeallocActions.pop_back();
89	    }
90	  });
91	
92	  for (auto &AAP : AAPs) {
93	    if (AAP.Finalize) {
94	      auto B = AAP.Finalize();
95	      if (const char *ErrMsg = B.getOutOfBandError())
96	        return make_error<StringError>(ErrMsg);
97	    }
98	    if (AAP.Dealloc)
99	      DeallocActions.push_back(std::move(AAP.Dealloc));
100	  }
101	
102	  RunDeallocActions.release();
103	  return DeallocActions;
104	}
105	
106	/// Run the given deallocation actions in revwerse order.
107	template <typename ReportErrorFn>
108	void runDeallocActions(std::vector<AllocAction> DAAs,
109	                       ReportErrorFn &&ReportError) {
110	  while (!DAAs.empty()) {
111	    auto B = DAAs.back()();
112	    if (const char *ErrMsg = B.getOutOfBandError())
113	      ReportError(make_error<StringError>(ErrMsg));
114	    DAAs.pop_back();
115	  }
116	}
117	
118	} // namespace orc_rt
119	
120	#endif // ORC_RT_ALLOCACTION_H
