13	#ifndef ORC_RT_SIMPLESYMBOLTABLE_H
14	#define ORC_RT_SIMPLESYMBOLTABLE_H
15	
16	#include "orc-rt/Error.h"
17	#include "orc-rt/move_only_function.h"
18	#include <string>
19	#include <string_view>
20	#include <unordered_map>
21	#include <vector>
22	
23	#define ORC_RT_SYMTAB_PAIR(sym) {{#sym}, reinterpret_cast<const void *>(&sym)}
24	
25	namespace orc_rt {
26	
27	/// A simple string-to-pointer symbol table. Symbols are added via
28	/// addSymbolsUnique, which rejects duplicates with an error.
29	class SimpleSymbolTable {
30	public:
31	  using SymbolTable = std::unordered_map<std::string, const void *>;
32	  using iterator = SymbolTable::const_iterator;
33	
34	  using MutatorFn = move_only_function<Error(SimpleSymbolTable &)>;
35	
36	  bool empty() const noexcept { return Symbols.empty(); }
37	  size_t size() const noexcept { return Symbols.size(); }
38	  iterator begin() const noexcept { return Symbols.begin(); }
39	  iterator end() const noexcept { return Symbols.end(); }
40	
41	  template <typename KeyT> decltype(auto) count(KeyT &&K) const {
42	    return Symbols.count(std::forward<KeyT>(K));
43	  }
44	
45	  template <typename KeyT> decltype(auto) at(KeyT &&K) const {
46	    return Symbols.at(std::forward<KeyT>(K));
47	  }
48	
49	  /// Adds symbol/address pairs from NewSymbols, first checking that all
50	  /// symbols in NewSymbols are unique (i.e. not previously defined).
51	  ///
52	  /// NewSymbols must not contain any internal duplicates.
53	  template <typename SymbolRangeT> Error addUnique(SymbolRangeT &&NewSymbols) {
54	
55	    // First check for incompatible duplicate definitions (duplicates are
56	    // only permitted if they resolve to the same address). Error out if any
57	    // incompatible defs are found.
58	    {
59	      std::vector<std::string_view> IncompatibleDefs;
60	      for (auto &[Name, Addr] : NewSymbols) {
61	        auto I = Symbols.find(Name);
62	        if (I == Symbols.end() || I->second == Addr)
63	          continue;
64	        if (Symbols.count(Name))
65	          IncompatibleDefs.push_back(Name);
66	      }
67	      if (!IncompatibleDefs.empty())
68	        return makeIncompatibleDefsError(std::move(IncompatibleDefs));
69	    }
70	
71	    // No duplicates. Add entries.
72	    for (auto &P : NewSymbols) {
73	      [[maybe_unused]] auto [I, Added] = Symbols.insert(P);
74	      assert((Added || I->second == P.second) &&
75	             "NewSymbols contains incompatible definitions");
76	    }
77	
78	    return Error::success();
79	  }
80	
81	private:
82	  static Error
83	  makeIncompatibleDefsError(std::vector<std::string_view> IncompatibleDefs);
84	
85	  SymbolTable Symbols;
86	};
87	
88	} // namespace orc_rt
89	
90	#endif // ORC_RT_SIMPLESYMBOLTABLE_H
