30	Expected<std::unique_ptr<SimpleNativeMemoryMap>>
31	SimpleNativeMemoryMap::Create(Session &S, SimpleSymbolTable &ST,
32	                              const char *InstanceName,
33	                              SimpleSymbolTable::MutatorFn AddInterface) {
34	
35	  std::unique_ptr<SimpleNativeMemoryMap> Instance(new SimpleNativeMemoryMap(S));
36	
37	  SimpleSymbolTable SNMMST;
38	  if (auto Err = AddInterface(SNMMST))
39	    return Err;
40	  std::pair<const char *, const void *> InstanceSym[] = {
41	      {InstanceName, static_cast<const void *>(Instance.get())}};
42	  if (auto Err = SNMMST.addUnique(InstanceSym))
43	    return std::move(Err);
44	
45	  if (auto Err = ST.addUnique(SNMMST))
46	    return std::move(Err);
47	
48	  return std::move(Instance);
49	}
