51	void SimpleNativeMemoryMap::reserve(OnReserveCompleteFn &&OnComplete,
52	                                    size_t Size) {
53	  if (Size % S.processInfo().pageSize()) {
54	    return OnComplete(make_error<StringError>(
55	        (std::ostringstream()
56	         << "SimpleNativeMemoryMap error: reserved size " << std::hex << Size
57	         << " is not a page-size multiple")
58	            .str()));
59	  }
60	
61	  auto Addr = hostOSMemoryReserve(Size);
62	  if (!Addr)
63	    return OnComplete(Addr.takeError());
64	
65	  {
66	    std::scoped_lock<std::mutex> Lock(M);
67	    assert(!Slabs.count(*Addr) &&
68	           "hostOSMemoryReserve returned duplicate addresses");
69	    Slabs.emplace(std::make_pair(*Addr, SlabInfo(Size)));
70	  }
71	
72	  OnComplete(*Addr);
73	}
74	
75	void SimpleNativeMemoryMap::release(OnReleaseCompleteFn &&OnComplete,
76	                                    void *Addr) {
77	  std::optional<SlabInfo> SI;
78	  {
79	    std::scoped_lock<std::mutex> Lock(M);
80	    auto I = Slabs.find(Addr);
81	    if (I != Slabs.end()) {
82	      SI = std::move(I->second);
83	      Slabs.erase(I);
84	    }
85	  }
86	
87	  if (!SI) {
88	    std::ostringstream ErrMsg;
89	    ErrMsg << "SimpleNativeMemoryMap error: release called on unrecognized "
90	              "address "
91	           << Addr;
92	    return OnComplete(make_error<StringError>(ErrMsg.str()));
93	  }
94	
95	  for (auto &[Addr, DAAs] : SI->DeallocActions)
96	    runDeallocActions(std::move(DAAs), ReportErrorsViaSession(S));
97	
98	  OnComplete(hostOSMemoryRelease(Addr, SI->Size));
99	}
100	
101	void SimpleNativeMemoryMap::releaseMultiple(OnReleaseCompleteFn &&OnComplete,
102	                                            std::vector<void *> Addrs) {
103	  releaseNext(std::move(OnComplete), std::move(Addrs), false, Error::success());
104	}
