106	void SimpleNativeMemoryMap::initialize(OnInitializeCompleteFn &&OnComplete,
107	                                       InitializeRequest IR) {
108	
109	  void *Base = nullptr;
110	
111	  // TODO: Record initialize segments for release.
112	  // std::vector<std::pair<void*, size_t>> InitializeSegments;
113	
114	  // Check segment validity before proceeding.
115	  for (auto &S : IR.Segments) {
116	
117	    if (S.Content.size() > S.Size) {
118	      return OnComplete(make_error<StringError>(
119	          (std::ostringstream()
120	           << "For segment [" << (void *)S.Address << ".."
121	           << (void *)(S.Address + S.Size) << "), "
122	           << " content size (" << std::hex << S.Content.size()
123	           << ") exceeds segment size (" << S.Size << ")")
124	              .str()));
125	    }
126	
127	    // Copy any requested content.
128	    if (!S.Content.empty())
129	      memcpy(S.Address, S.Content.data(), S.Content.size());
130	
131	    // Zero-fill the rest of the section.
132	    if (size_t ZeroFillSize = S.Size - S.Content.size())
133	      memset(S.Address + S.Content.size(), 0, ZeroFillSize);
134	
135	    if (auto Err = hostOSMemoryProtect(S.Address, S.Size, S.AG.getMemProt()))
136	      return OnComplete(std::move(Err));
137	
138	    switch (S.AG.getMemLifetime()) {
139	    case MemLifetime::Standard:
140	      if (!Base || S.Address < Base)
141	        Base = S.Address;
142	      break;
143	    case MemLifetime::Finalize:
144	      // TODO: Record finalize segment for release.
145	      // FinalizeSegments.push_back({S.Address, S.Size});
146	      break;
147	    }
148	  }
149	
150	  if (!Base)
151	    return OnComplete(
152	        make_error<StringError>("SimpleNativeMemoryMap initialize error: "
153	                                "finalization requires at least "
154	                                "one standard-lifetime segment"));
155	
156	  auto DeallocActions =
157	      runFinalizeActions(std::move(IR.AAPs), ReportErrorsViaSession(S));
158	  if (!DeallocActions)
159	    return OnComplete(DeallocActions.takeError());
160	
161	  if (auto Err = recordDeallocActions(Base, std::move(*DeallocActions))) {
162	    runDeallocActions(std::move(*DeallocActions), ReportErrorsViaSession(S));
163	    return OnComplete(std::move(Err));
164	  }
165	
166	  OnComplete(Base);
167	}
168	
169	void SimpleNativeMemoryMap::deinitialize(OnDeinitializeCompleteFn &&OnComplete,
170	                                         void *Base) {
171	  std::vector<AllocAction> DAAs;
172	
173	  {
174	    std::unique_lock<std::mutex> Lock(M);
175	    auto *SI = findSlabInfoFor(Base);
176	    if (!SI) {
177	      Lock.unlock();
178	      return OnComplete(makeBadSlabError(Base, "deinitialize"));
179	    }
180	
181	    auto I = SI->DeallocActions.find(Base);
182	    if (I == SI->DeallocActions.end()) {
183	      Lock.unlock();
184	      std::ostringstream ErrMsg;
185	      ErrMsg
186	          << "SimpleNativeMemoryMap deinitialize error: no deallocate actions "
187	             "registered for segment base address "
188	          << Base;
189	      return OnComplete(make_error<StringError>(ErrMsg.str()));
190	    }
191	
192	    DAAs = std::move(I->second);
193	    SI->DeallocActions.erase(I);
194	  }
195	
196	  runDeallocActions(std::move(DAAs), ReportErrorsViaSession(S));
197	  OnComplete(Error::success());
198	}
