200	void SimpleNativeMemoryMap::deinitializeMultiple(
201	    OnDeinitializeCompleteFn &&OnComplete, std::vector<void *> Bases) {
202	  deinitializeNext(std::move(OnComplete), std::move(Bases), false,
203	                   Error::success());
204	}
