213	void SimpleNativeMemoryMap::onShutdown(Service::OnCompleteFn OnComplete) {
214	  // TODO: Establish a clear order to run deallocate actions across slabs,
215	  // object boundaries.
216	
217	  // Collect slab base addresses for removal.
218	  std::vector<void *> Bases;
219	  {
220	    std::scoped_lock<std::mutex> Lock(M);
221	    for (auto &[Base, _] : Slabs)
222	      Bases.push_back(Base);
223	  }
224	
225	  shutdownNext(std::move(OnComplete), std::move(Bases));
