228	void SimpleNativeMemoryMap::releaseNext(OnReleaseCompleteFn &&OnComplete,
229	                                        std::vector<void *> Addrs,
230	                                        bool AnyError, Error LastErr) {
231	  if (LastErr) {
232	    S.reportError(std::move(LastErr));
233	    AnyError |= true;
234	  }
235	
236	  if (Addrs.empty()) {
237	    if (!AnyError)
238	      return OnComplete(Error::success());
239	
240	    return OnComplete(
241	        make_error<StringError>("Failed to release some addresses"));
242	  }
243	
244	  void *NextAddr = Addrs.back();
245	  Addrs.pop_back();
246	
247	  release(
248	      [this, OnComplete = std::move(OnComplete), AnyError = AnyError,
249	       Addrs = std::move(Addrs)](Error Err) mutable {
250	        releaseNext(std::move(OnComplete), std::move(Addrs), AnyError,
251	                    std::move(Err));
252	      },
253	      NextAddr);
254	}
255	
256	void SimpleNativeMemoryMap::deinitializeNext(
257	    OnDeinitializeCompleteFn &&OnComplete, std::vector<void *> Addrs,
258	    bool AnyError, Error LastErr) {
259	  if (LastErr) {
260	    S.reportError(std::move(LastErr));
261	    AnyError |= true;
262	  }
263	
264	  if (Addrs.empty()) {
265	    if (!AnyError)
266	      return OnComplete(Error::success());
267	
268	    return OnComplete(
269	        make_error<StringError>("Failed to deinitialize some addresses"));
270	  }
271	
272	  void *NextAddr = Addrs.back();
273	  Addrs.pop_back();
274	
275	  deinitialize(
276	      [this, OnComplete = std::move(OnComplete), AnyError = AnyError,
277	       Addrs = std::move(Addrs)](Error Err) mutable {
278	        deinitializeNext(std::move(OnComplete), std::move(Addrs), AnyError,
279	                         std::move(Err));
280	      },
281	      NextAddr);
282	}
283	
284	void SimpleNativeMemoryMap::shutdownNext(Service::OnCompleteFn OnComplete,
285	                                         std::vector<void *> Bases) {
286	  if (Bases.empty())
287	    return OnComplete();
288	
289	  auto *Base = Bases.back();
290	  Bases.pop_back();
291	
292	  release(
293	      [this, Bases = std::move(Bases),
294	       OnComplete = std::move(OnComplete)](Error Err) mutable {
295	        if (Err) {
296	          // TODO: Log release error?
297	          consumeError(std::move(Err));
298	        }
299	        shutdownNext(std::move(OnComplete), std::move(Bases));
300	      },
301	      Base);
302	}
303	
304	Error SimpleNativeMemoryMap::makeBadSlabError(void *Base, const char *Op) {
305	  std::ostringstream ErrMsg;
306	  ErrMsg << "SimpleNativeMemoryMap " << Op << " error: segment base address "
307	         << Base << " does not fall within an allocated slab";
308	  return make_error<StringError>(ErrMsg.str());
309	}
310	
311	SimpleNativeMemoryMap::SlabInfo *
312	SimpleNativeMemoryMap::findSlabInfoFor(void *Base) {
313	  // NOTE: We assume that the caller is holding a lock for M.
314	  auto I = Slabs.upper_bound(Base);
315	  if (I == Slabs.begin())
316	    return nullptr;
317	
318	  --I;
319	  if (reinterpret_cast<char *>(I->first) + I->second.Size <=
320	      reinterpret_cast<char *>(Base))
321	    return nullptr;
322	
323	  return &I->second;
324	}
325	
326	Error SimpleNativeMemoryMap::recordDeallocActions(
327	    void *Base, std::vector<AllocAction> DeallocActions) {
328	
329	  std::unique_lock<std::mutex> Lock(M);
330	  auto *SI = findSlabInfoFor(Base);
331	  if (!SI) {
332	    Lock.unlock();
333	    return makeBadSlabError(Base, "deinitialize");
334	  }
335	
336	  auto I = SI->DeallocActions.find(Base);
337	  if (I != SI->DeallocActions.end()) {
338	    Lock.unlock();
339	    std::ostringstream ErrMsg;
340	    ErrMsg << "SimpleNativeMemoryMap initialize error: segment base address "
341	              "reused in subsequent initialize call";
342	    return make_error<StringError>(ErrMsg.str());
343	  }
344	
345	  SI->DeallocActions[Base] = std::move(DeallocActions);
346	  return Error::success();
347	}
