47	void NativeDylibManager::load(OnLoadCompleteFn &&OnComplete, std::string Path) {
48	  // Empty path -> global handle; no shutdown callback (RTLD_DEFAULT
49	  // mustn't be dlclose'd).
50	  if (Path.empty())
51	    return OnComplete(hostOSGetGlobalLookupHandle());
52	
53	  auto H = hostOSLoadLibrary(Path);
54	  if (!H)
55	    return OnComplete(H.takeError());
56	
57	  // Capture S by reference, rather than this, so that the callback remains
58	  // valid even if the NativeDylibManager is destroyed prior to shutdown.
59	  S.addOnShutdown([&S = this->S, Handle = *H]() {
60	    if (auto Err = hostOSUnloadLibrary(Handle))
61	      S.reportError(std::move(Err));
62	  });
63	  OnComplete(std::move(H));
64	}
65	
66	void NativeDylibManager::lookup(OnLookupCompleteFn &&OnLookupComplete,
67	                                void *Handle, SymbolLookupSet Symbols) {
68	  std::vector<std::string> Names;
69	  Names.reserve(Symbols.size());
70	  for (auto &S : Symbols)
71	    Names.push_back(std::move(S.first));
72	
73	  auto Addrs = hostOSLibraryLookup(Handle, Names);
74	
75	  // Convert weak-missing entries (empty optional from hostOSLibraryLookup)
76	  // to a present zero address. This matches the resolve semantics of
77	  // llvm::orc::rt_bootstrap::SimpleExecutorDylibManager: an empty optional
78	  // in the result signals a missing required symbol, while a missing
79	  // weakly-referenced symbol is reported as a zero address.
80	  for (size_t I = 0, E = Symbols.size(); I != E; ++I)
81	    if (!Addrs[I] && Symbols[I].second == WeaklyReferencedSymbol)
82	      Addrs[I] = nullptr;
83	
84	  OnLookupComplete(std::move(Addrs));
85	}
