48	
49	Error StandaloneMachOUnwindInfoRegistrar::UnwindInfoMap::registerRanges(
50	    const std::vector<ExecutorAddrRange> &CodeRanges,
51	    const DynamicUnwindSections &Info) {
52	  std::scoped_lock<std::mutex> Lock(M);
53	  for (auto &CodeRange : CodeRanges) {
54	    // TODO: We're assuming safe conversion from ExecutorAddr to uintptr_t
55	    //       here. In the future we should either check, or make sure that
56	    //       invalid values aren't deserializable (by switching the wire
57	    //       representation to match the pointer size).
58	    if (CodeRange.Start.getValue() > std::numeric_limits<uintptr_t>::max() ||
59	        CodeRange.End.getValue() > std::numeric_limits<uintptr_t>::max())
60	      return make_error<StringError>(
61	          "Invalid code-range for unwind-info registration");
62	
63	    uintptr_t Start = CodeRange.Start.getValue();
64	    uintptr_t End = CodeRange.End.getValue();
65	
66	    // Ignore empty ranges.
67	    // FIXME: Should we hard-error on these instead?
68	    if (Start == End)
69	      continue;
70	
71	    // Check for overlap with neighboring ranges (including any added earlier
72	    // in this call, since each successful insertion is visible to subsequent
73	    // iterations).
74	    auto MakeRangeOverlapError = [] {
75	      return make_error<StringError>(
76	          "Code-range for unwind-info registration overlaps an existing range");
77	    };
78	    auto I = Ranges.upper_bound(Start);
79	    if (I != Ranges.end() && I->first < End)
80	      return MakeRangeOverlapError();
81	
82	    if (I != Ranges.begin()) {
83	      auto PrevI = std::prev(I);
84	      if (PrevI->second.End > Start)
85	        return MakeRangeOverlapError();
86	    }
87	
88	    Ranges.emplace_hint(I, Start, Entry{Info, End});
89	  }
90	
91	  return Error::success();
92	}
93	
94	Error StandaloneMachOUnwindInfoRegistrar::UnwindInfoMap::deregisterRanges(
95	    const std::vector<ExecutorAddrRange> &CodeRanges) {
96	  std::scoped_lock<std::mutex> Lock(M);
97	  for (auto &CodeRange : CodeRanges) {
98	    auto I = Ranges.find(CodeRange.Start.getValue());
99	    if (I == Ranges.end())
100	      return make_error<StringError>(
101	          "No unwind-info sections registered for range");
102	    Ranges.erase(I);
103	  }
104	  return Error::success();
105	}
