107	std::optional<StandaloneMachOUnwindInfoRegistrar::DynamicUnwindSections>
108	StandaloneMachOUnwindInfoRegistrar::UnwindInfoMap::lookup(
109	    uintptr_t Addr) const {
110	  std::scoped_lock<std::mutex> Lock(M);
111	  auto I = Ranges.upper_bound(Addr);
112	  if (I == Ranges.begin())
113	    return std::nullopt;
114	  --I;
115	  if (Addr >= I->second.End)
116	    return std::nullopt;
117	  return I->second.Info;
118	}
