137	Error StandaloneMachOUnwindInfoRegistrar::registerWithLibunwind() {
138	  // Check whether the necessary libunwind APIs are available, as they were
139	  // only introduced in macOS 15.
140	  if (!__unw_add_find_dynamic_unwind_sections ||
141	      !__unw_remove_find_dynamic_unwind_sections)
142	    return make_error<StringError>(
143	        "libunwind unwind-info registration APIs not available");
144	
145	  std::scoped_lock<std::mutex> Lock(LibunwindRegistrationMtx);
146	
147	  // If we've already registered then just bump the ref count and exit.
148	  if (LibunwindRegistrationCount > 0) {
149	    ++LibunwindRegistrationCount;
150	    return Error::success();
151	  }
152	
153	  // Try to register.
154	  // findUnwindInfoSections has the same call ABI as libunwind expects, since
155	  // DynamicUnwindSections is laid out identically to
156	  // unw_dynamic_unwind_sections, so the reinterpret_cast here should be safe
157	  // in practice.
158	  if (__unw_add_find_dynamic_unwind_sections(
159	          reinterpret_cast<unw_find_dynamic_unwind_sections>(
160	              findUnwindInfoSections)) != 0)
161	    return make_error<StringError>(
162	        "libunwind find-dynamic-unwind-sections registration failed");
163	
164	  // If we succeeded, bump the ref count.
165	  ++LibunwindRegistrationCount;
166	  return Error::success();
167	}
