169	void StandaloneMachOUnwindInfoRegistrar::deregisterWithLibunwind() {
170	  std::scoped_lock<std::mutex> Lock(LibunwindRegistrationMtx);
171	  if (--LibunwindRegistrationCount == 0)
172	    __unw_remove_find_dynamic_unwind_sections(
173	        reinterpret_cast<unw_find_dynamic_unwind_sections>(
174	            findUnwindInfoSections));
175	}
